"use strict";
// ==========================================
// 03-strings-and-conditions.ts — Strings & Booleans
// ==========================================
let department = "IT";
let isEmployeeActive = true;
console.log("=== 03-strings-and-conditions ===");
if (isEmployeeActive && department === "IT") {
    console.log("Active IT employee");
}
else {
    console.log("Employee not active in IT");
}
